mapper.update:
UPDATE `warehouse_item`
SET item_code = #{itemCode}
WHERE id = #{id} AND item_code IS NULL AND is_deleted = 0

UPDATE `warehouse_item` SET is_deleted = 1, status = 0 WHERE id IN
#{id}
AND is_deleted = 0

UPDATE `warehouse_item`
SET status = #{status}
WHERE id = #{id} AND is_deleted = 0

UPDATE `warehouse_item`
SET stock_qty = #{stockQty}
WHERE id = #{id} AND is_deleted = 0 AND status = 1

mapper.select:
SELECT FROM `warehouse_item` wi LEFT JOIN `user` u ON u.id = wi.user_id LEFT JOIN `user` fou ON fou.id = wi.farm_owner_id LEFT JOIN `user` iou ON iou.id = wi.inbound_operator_id LEFT JOIN `warehouse_record` lor ON lor.id = ( SELECT wr.id FROM `warehouse_record` wr WHERE wr.item_id = wi.id AND wr.record_type = 2 AND wr.status = 1 ORDER BY wr.id DESC LIMIT 1 ) LEFT JOIN `user` lou ON lou.id = lor.operator_id
AND wi.is_deleted = 0 AND wi.farm_owner_id = #{userId} AND wi.item_name LIKE CONCAT('%', #{itemName}, '%') AND wi.item_code LIKE CONCAT('%', #{itemCode}, '%') AND wi.category = #{category} AND wi.status = #{status}
ORDER BY wi.id DESC

SELECT COUNT(1)
FROM `warehouse_item`
WHERE farm_owner_id = #{userId}
  AND item_code = #{itemCode}
AND id != #{excludeId}

SELECT FROM `warehouse_item` wi LEFT JOIN `user` u ON u.id = wi.user_id LEFT JOIN `user` fou ON fou.id = wi.farm_owner_id LEFT JOIN `user` iou ON iou.id = wi.inbound_operator_id LEFT JOIN `warehouse_record` lor ON lor.id = ( SELECT wr.id FROM `warehouse_record` wr WHERE wr.item_id = wi.id AND wr.record_type = 2 AND wr.status = 1 ORDER BY wr.id DESC LIMIT 1 ) LEFT JOIN `user` lou ON lou.id = lor.operator_id WHERE wi.is_deleted = 0 AND wi.status = 1 AND wi.farm_owner_id IS NOT NULL AND wi.farm_owner_id = #{farmOwnerId} AND wi.category = #{category}
AND (wi.item_name LIKE CONCAT('%', #{keyword}, '%') OR wi.item_code LIKE CONCAT('%', #{keyword}, '%') OR wi.specification LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY wi.id DESC

SELECT COUNT(1) FROM `warehouse_item`
WHERE is_deleted = 0 AND farm_owner_id IS NOT NULL
AND farm_owner_id = #{farmOwnerId}

SELECT COALESCE(SUM(stock_qty), 0) FROM `warehouse_item`
WHERE is_deleted = 0 AND farm_owner_id IS NOT NULL
AND farm_owner_id = #{farmOwnerId}
